const app=document.querySelector('#app');
const projectId=location.pathname.match(/^\/projects\/(\d+)$/)?.[1];
async function request(url,options){const response=await fetch(url,options);return response}
if(projectId){document.querySelector('#project-form').remove();document.querySelector('section[aria-label="Projects"]').remove();const response=await request(`/api/projects/${projectId}`);const project=response.ok?await response.json():null;const heading=document.querySelector('h1');heading.textContent=project?.name||'Project not found';const back=document.createElement('button');back.type='button';back.textContent='Projects';back.onclick=()=>location.href='/';app.append(back);if(project?.archived){const notice=document.createElement('p');notice.textContent='Archived project';app.append(notice)}const form=document.querySelector('#task-form');form.hidden=false;form.querySelector('button').disabled=!!project?.archived;const alert=document.querySelector('#task-alert'),tasks=document.createElement('section'),list=document.createElement('div');tasks.setAttribute('aria-label','Tasks');tasks.append(list);app.append(tasks);
 async function renderTasks(){const all=await(await request(`/api/projects/${projectId}/tasks`)).json(),filter=document.querySelector('#task-filter').value;list.replaceChildren();for(const task of all.filter(t=>filter==='All'||(filter==='Open'?!t.completed:!!t.completed))){const row=document.createElement('div');row.dataset.testid='task-row';const label=document.createElement('label'),checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=!!task.completed;checkbox.disabled=!!project?.archived;checkbox.setAttribute('aria-label',`Complete ${task.title}`);checkbox.onchange=async()=>{await request(`/api/projects/${projectId}/tasks/${task.id}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({completed:checkbox.checked})});await renderTasks()};label.append(checkbox,document.createTextNode(task.title));row.append(label);list.append(row)}}
 document.querySelector('#task-filter').addEventListener('change',renderTasks);form.onsubmit=async event=>{event.preventDefault();alert.hidden=true;const input=document.querySelector('#task-title'),title=input.value.trim();if(!title){alert.textContent='Task title is required';alert.hidden=false;return}const result=await request(`/api/projects/${projectId}/tasks`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({title})});if(result.ok){input.value='';await renderTasks()}};if(project)await renderTasks();
}else{const list=document.querySelector('#projects'),alert=document.querySelector('#alert');const filter=document.createElement('select');filter.setAttribute('aria-label','Project filter');for(const value of ['Active','Archived']){const option=document.createElement('option');option.textContent=value;filter.append(option)}document.querySelector('section[aria-label="Projects"] h2').after(filter);
 async function render(){const archived=filter.value==='Archived',projects=await(await request(`/api/projects?archived=${archived}`)).json();list.replaceChildren();for(const project of projects){const row=document.createElement('div');row.className='project-row';row.dataset.testid='project-row';const name=document.createElement('span');name.textContent=project.name;const summary=document.createElement('span');summary.dataset.testid='project-summary';summary.textContent=`${project.completedCount}/${project.totalCount} completed`;const open=document.createElement('button');open.textContent='Open project';open.onclick=()=>location.href=`/projects/${project.id}`;const action=document.createElement('button');action.textContent=archived?'Restore project':'Archive project';action.onclick=async()=>{await request(`/api/projects/${project.id}/${archived?'restore':'archive'}`,{method:'POST'});await render()};row.append(name,summary,open,action);list.append(row)}}
 filter.addEventListener('change',render);document.querySelector('#project-form').onsubmit=async event=>{event.preventDefault();alert.hidden=true;const input=document.querySelector('#project-name'),name=input.value.trim();if(!name){alert.textContent='Project name is required';alert.hidden=false;return}const response=await request('/api/projects',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name})});if(response.ok){input.value='';await render()}};await render()}

import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const dbPath = process.env.DB_PATH || path.join(process.cwd(), 'workboard.sqlite');
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, archived INTEGER NOT NULL DEFAULT 0)`);
// Upgrade databases created by earlier checkpoints.
if (!db.prepare("PRAGMA table_info(projects)").all().some(column => column.name === 'archived')) db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0');
db.exec(`CREATE TABLE IF NOT EXISTS tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, title TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)`);
const listProjects = db.prepare('SELECT p.id,p.name,p.archived,COUNT(t.id) AS totalCount,COALESCE(SUM(t.completed),0) AS completedCount FROM projects p LEFT JOIN tasks t ON t.project_id=p.id WHERE p.archived=? GROUP BY p.id ORDER BY p.id');
const getProject = db.prepare('SELECT id,name,archived FROM projects WHERE id=?');
const addProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const setArchived = db.prepare('UPDATE projects SET archived=? WHERE id=?');
const listTasks = db.prepare('SELECT id,project_id AS projectId,title,completed FROM tasks WHERE project_id=? ORDER BY id');
const addTask = db.prepare('INSERT INTO tasks (project_id,title) VALUES (?,?)');
const updateTask = db.prepare('UPDATE tasks SET completed=? WHERE id=? AND project_id=? AND EXISTS (SELECT 1 FROM projects WHERE id=? AND archived=0)');
const htmlPath = fileURLToPath(new URL('./public/index.html', import.meta.url));
const jsPath = fileURLToPath(new URL('./public/app.js', import.meta.url));
const cssPath = fileURLToPath(new URL('./public/style.css', import.meta.url));
function send(res,status,body,type='application/json; charset=utf-8'){res.writeHead(status,{'content-type':type,'cache-control':'no-store'});res.end(body)}
async function bodyJson(req){let data='';for await(const chunk of req){data+=chunk;if(data.length>100000)throw new Error('Request too large')}return JSON.parse(data||'{}')}
const server=http.createServer(async(req,res)=>{const url=new URL(req.url,'http://localhost');try{
 if(req.method==='GET'&&url.pathname==='/health')return send(res,200,JSON.stringify({status:'ok'}));
 if(req.method==='GET'&&url.pathname==='/api/projects')return send(res,200,JSON.stringify(listProjects.all(url.searchParams.get('archived')==='true'?1:0)));
 if(req.method==='POST'&&url.pathname==='/api/projects'){const data=await bodyJson(req),name=typeof data.name==='string'?data.name.trim():'';if(!name)return send(res,400,JSON.stringify({error:'Project name is required'}));const result=addProject.run(name);return send(res,201,JSON.stringify({id:Number(result.lastInsertRowid),name,archived:0}))}
 const archiveMatch=url.pathname.match(/^\/api\/projects\/(\d+)\/(archive|restore)$/);if(req.method==='POST'&&archiveMatch){const result=setArchived.run(archiveMatch[2]==='archive'?1:0,Number(archiveMatch[1]));return result.changes?send(res,200,JSON.stringify({ok:true})):send(res,404,JSON.stringify({error:'Not found'}))}
 const tasksMatch=url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);if(tasksMatch){const id=Number(tasksMatch[1]),project=getProject.get(id);if(!project)return send(res,404,JSON.stringify({error:'Not found'}));if(req.method==='GET')return send(res,200,JSON.stringify(listTasks.all(id)));if(req.method==='POST'){if(project.archived)return send(res,403,JSON.stringify({error:'Archived project'}));const data=await bodyJson(req),title=typeof data.title==='string'?data.title.trim():'';if(!title)return send(res,400,JSON.stringify({error:'Task title is required'}));const result=addTask.run(id,title);return send(res,201,JSON.stringify({id:Number(result.lastInsertRowid),projectId:id,title,completed:0}))}}
 const taskMatch=url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);if(req.method==='PATCH'&&taskMatch){const data=await bodyJson(req);if(typeof data.completed!=='boolean')return send(res,400,JSON.stringify({error:'Invalid completion state'}));const id=Number(taskMatch[1]),result=updateTask.run(data.completed?1:0,Number(taskMatch[2]),id);return result.changes?send(res,200,JSON.stringify({ok:true})):send(res,404,JSON.stringify({error:'Not found'}))}
 const projectMatch=url.pathname.match(/^\/api\/projects\/(\d+)$/);if(req.method==='GET'&&projectMatch){const project=getProject.get(Number(projectMatch[1]));return project?send(res,200,JSON.stringify(project)):send(res,404,JSON.stringify({error:'Not found'}))}
 if(req.method==='GET'&&(url.pathname==='/'||/^\/projects\/\d+$/.test(url.pathname)))return send(res,200,await readFile(htmlPath,'utf8'),'text/html; charset=utf-8');
 if(req.method==='GET'&&url.pathname==='/app.js')return send(res,200,await readFile(jsPath,'utf8'),'text/javascript; charset=utf-8');if(req.method==='GET'&&url.pathname==='/style.css')return send(res,200,await readFile(cssPath,'utf8'),'text/css; charset=utf-8');send(res,404,JSON.stringify({error:'Not found'}));
 }catch(error){send(res,error.message==='Request too large'?413:400,JSON.stringify({error:'Invalid request'}))}});
const port=Number(process.env.PORT||8080);server.listen(port,'0.0.0.0',()=>console.log(`Workboard listening on ${port}`));
